function out=plot_q7_aoe_group_roi()
repo=fileparts(fileparts(fileparts(mfilename('fullpath'))));root=fullfile(repo,'results','q7_interaction_aoe','cohort_specification');out=fullfile(root,'figures_long45_allQC');if ~isfolder(out),mkdir(out);end;I=readtable(fullfile(root,'q7_interaction_aoe_individual_ROI_long45_allQC_n30.csv'),'TextType','string');G=readtable(fullfile(root,'q7_interaction_aoe_group_channel_summary_n30.csv'),'TextType','string');K=unique(I(I.hemoglobin=="HbO",{'roi','laterality'}),'rows','stable');f=figure('Color','w','Position',[100 100 1800 1050]);tiledlayout(2,1);for j=1:2,hb=["HbO","HbR"];U=I(I.hemoglobin==hb(j),:);M=nan(30,height(K));for k=1:height(K),v=U(U.roi==K.roi(k)&U.laterality==K.laterality(k),:);M(:,k)=v.mean_contrast_beta;end;nexttile;z=max(abs(M(:)));imagesc(M,[-z z]);colormap(gca,bwr(256));cb=colorbar;cb.Color='k';set(gca,'XTick',1:height(K),'XTickLabel',strcat(K.roi," | ",K.laterality),'XTickLabelRotation',35,'YTick',1:30,'YTickLabel',compose('%03d',1:30),'XColor','k','YColor','k');xlabel('Broad ROI | laterality','Color','k');ylabel('Subject','Color','k');title(hb(j),'Color','k');end;sgtitle('Q7 AOE Layer 1: individual ROI beta | interaction','Color','k');exportgraphics(f,fullfile(out,'q7_aoe_layer1_individual_roi_heatmaps_long45_allQC.png'),'Resolution',220);close(f);
f=figure('Color','w','Position',[100 100 1900 700]);tiledlayout(2,1);for j=1:2,hb=["HbO","HbR"];U=G(G.hemoglobin==hb(j)&G.channel_type=="Long",:);nexttile;v=U.mean_contrast_beta';z=max(abs(v));imagesc(v,[-z z]);colormap(gca,bwr(256));cb=colorbar;cb.Color='k';set(gca,'YTick',1,'YTickLabel',hb(j),'XTick',1:height(U),'XTickLabel',compose('ch%d',U.channel_index),'XTickLabelRotation',45,'XColor','k','YColor','k');xlabel('Long channel','Color','k');title('Group beta; black dot = uncorrected p<.05','Color','k');hold on;ix=U.group_p_two_sided<.05;plot(find(ix),ones(sum(ix),1),'ko','MarkerFaceColor','k');end;sgtitle('Q7 AOE Layer 3: long-channel interaction effects','Color','k');exportgraphics(f,fullfile(out,'q7_aoe_layer3_long_channel_effects_long45_allQC.png'),'Resolution',220);close(f);fprintf('Saved Q7 AOE figures to %s\n',out);
end
function c=bwr(n),if nargin<1,n=256;end;x=linspace(0,1,n)';c=[interp1([0 .5 1],[0 1 1],x),interp1([0 .5 1],[0 1 0],x),interp1([0 .5 1],[1 1 0],x)];end
